function validate(input) {
  const [{ Friends = [] }] = input;
  const seen = new Set();
  for (const [a, b] of Friends) {
    if (a === null || b === null) return 'Both user ids are required.';
    if (a === b) return `User ${a} cannot be friends with themself.`;
    const key = `${a},${b}`;
    if (seen.has(key)) return `The row (${a}, ${b}) appears twice.`;
    seen.add(key);
  }
  return null;
}

