function generate(rand, size) {
  const users = size === 'small' ? 2 + Math.floor(rand() * 6) : 400;
  const target = size === 'small' ? Math.floor(rand() * 9) : 2000;
  const seen = new Set(), Friends = [];
  let attempts = 0;
  while (Friends.length < target && attempts++ < target * 20) {
    let a = 1 + Math.floor(rand() * users), b = 1 + Math.floor(rand() * users);
    // In large cases most friendships stay inside small clusters, so many pairs do share friends.
    if (size === 'large' && rand() < 0.5) b = Math.min(users, Math.max(1, a + Math.floor(rand() * 9) - 4));
    if (a === b) continue;
    const key = a < b ? `${a},${b}` : `${b},${a}`;
    if (seen.has(key)) continue;
    seen.add(key);
    // Mostly smaller id first, as on LeetCode, but sometimes the other way round.
    if ((a > b) !== (rand() < 0.25)) [a, b] = [b, a];
    Friends.push([a, b]);
  }
  return [{ Friends }];
}
